                 new("Return later or finish", "Close Explore to continue later, or choose Done when finished. Copying or exporting does not finish the task.", "Reopening restores your last stage without contacting AI. Normal workspaces keep a protected local checkpoint. Private workspaces keep unfinished work only while Tern is open.")], CommandIds.AskKnowledge),
            new("share-answer", "Share an answer with someone", "Use this when your manager or team needs the answer from your notes.",
                "After an answer, choose how to share it. Tern prepares and checks one complete report. Every format reuses that reviewed report. Email is built on this computer from its main points; PDF, note and print keep the full report. Switching formats does not ask AI again.",
                "Get an answer in Explore your notes first. Printing needs a printer installed in Windows.",
                "Hi,\n\nWe launch on 14 April. QA must approve by 7 April.\n\nSources: launch-plan.md, meeting-12.md",
                "A professional executive email, or a full report with an executive summary, detailed findings, exact evidence, next actions, limitations and a blank decision or review record.",
                "If Print is unavailable, add a printer in Windows Settings. If the last button is grey, tick I reviewed this report. If the report check finds problems, expand What needs checking for a short explanation or choose Ask AI to correct these issues for help. The checked new draft needs your review again before sharing. Failed or out-of-date corrections keep your wording and issues. Nothing exports automatically. After editing the report yourself, check it again before requesting correction.",
                [new("Find the choices", "On the answer screen, look under What would you like to do with this answer?", "Four options appear."),
                 new("Choose one", "Choose Copy for email, Save as PDF, Add to my note or Print, then Use this checked report.", "The same checked report opens for review; choosing another format does not ask AI again."),
                 new("Check the report", "Choose Preview report to read the formatted report. Fix anything wrong, press Check report if you made edits, then tick I reviewed this report. Check the executive summary, detailed findings, quotations, source headings and lines, and final actions. Then press the main button. You can use another format without reviewing the unchanged report again.", "The complete report is checked before it is ready. If AI stops before a large report is finished, Tern completes smaller independent sections; progress shows the current step. Email uses that checked content without another AI request. Editing the report or changing its sources requires a new check. These checks help you review; they do not prove every conclusion."),
                 new("Send it yourself", "Paste the executive summary into your email app, check it and send it. Add the full PDF yourself if needed; copying does not attach a file.", "Tern never sends a message by itself. Copying or exporting keeps the task available for another format until you choose Done.")], CommandIds.AskKnowledge),
        ];
        var writingShortcut = Gesture.Describe(registry.GetGesture(CommandIds.AskAI));
        if (writingShortcut.Length == 0) writingShortcut = "Edit → Write with AI";
        return lessons.Select(lesson => lesson with
        {
            Course = CourseFor(lesson.Id),
            Why = lesson.Why.Replace("Ctrl+Shift+Space", writingShortcut, StringComparison.Ordinal),
            Result = lesson.Result.Replace("Ctrl+Shift+Space", writingShortcut, StringComparison.Ordinal),
            Steps = lesson.Steps.Select(step => step with { Action = step.Action.Replace("Ctrl+Shift+Space", writingShortcut, StringComparison.Ordinal) }).ToArray(),
        }).ToArray();
    }

    private static string CourseFor(string id) => id switch
    {
        "write" or "open" or "url" or "read" or "save" or "practice" => "COURSE 1 · GETTING STARTED",
        "format" or "find" or "images" or "templates" or "recover" => "COURSE 2 · WRITING WELL",
        "pdf" or "print" => "COURSE 3 · SHARING DOCUMENTS",
        "organize" or "search-notes" => "COURSE 4 · ORGANIZING YOUR NOTES",
        _ => "COURSE 5 · WORKING WITH AI",
    };
}
